```
#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int anterior;
    cin >> anterior;
    int subidas = 0;
    for (int i = 1; i < n; ++i) {
        int x;
        cin >> x;
        if (x > anterior) ++subidas;
        anterior = x;
    }
    cout << subidas << endl;
}
```
Se lee el primer elemento fuera del bucle (n>=1 garantiza que existe) y se compara cada nuevo elemento con el anterior. No hace falta guardar la secuencia.

