#include <iostream>
using namespace std;

// @pre x >= 0
// @post retorna la suma de los digitos de x en base 256
int suma_digitos(long long x) {
    int s = 0;
    while (x > 0) {
        s += x % 256;
        x = x / 256;
    }
    return s;
}

// @pre x >= 0
// @post retorna cuantos digitos de x en base 256 son distintos de cero
int no_nulos(long long x) {
    int c = 0;
    while (x > 0) {
        if (x % 256 != 0) ++c;
        x = x / 256;
    }
    return c;
}

int main() {
    int t;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        long long x;
        cin >> x;
        cout << suma_digitos(x) << ' ' << no_nulos(x) << endl;
    }
}
```
Caso x=0: el bucle no entra y ambas devuelven 0, correcto. Se usa long long por seguridad frente al rango.

