#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int minim;
    cin >> minim;
    int cuantos = 1;
    for (int i = 1; i < n; ++i) {
        int x;
        cin >> x;
        if (x < minim) {
            minim = x;
            cuantos = 1;
        } else if (x == minim) {
            ++cuantos;
        }
    }
    cout << minim << ' ' << cuantos << endl;
}
```
Al aparecer un nuevo mínimo estricto se reinicia el contador a 1; si es igual se incrementa.

