#include <iostream>
using namespace std;

// @pre x >= 0, y >= 0
// @post retorna la suma de |dx - dy| sobre cada posicion de digito, con 0 para los digitos ausentes
int dif_digitos(int x, int y) {
    if (x == 0 and y == 0) return 0;
    int dx = x % 10;
    int dy = y % 10;
    int d = dx - dy;
    if (d < 0) d = -d;
    return d + dif_digitos(x / 10, y / 10);
}

int main() {
    int x, y;
    cin >> x >> y;
    cout << dif_digitos(x, y) << endl;
}
```
Salida correcta del ejemplo: 7 (el valor 6 que aparece en el ejemplo del enunciado es un error de redacción; el cálculo detallado da 2+2+2+1=7).

