#include <iostream>

int	main(void)
{
	int	n;
	int	prev;
	int	curr;
	int	count;
	int	i;

	if (!(std::cin >> n) || n < 1)
		return (1);
	std::cin >> prev;
	count = 0;
	i = 1;
	while (i < n)
	{
		std::cin >> curr;
		if (curr > prev)
			count += 1;
		prev = curr;
		i += 1;
	}
	std::cout << count << '\n';
	return (0);
}
